shellCommands.command:
/bin/bash -lc "cat > /tmp/orbit-browser-check/check.mjs <<'EOF'
import { chromium } from 'playwright';
import assert from 'node:assert/strict';
const browser = await chromium.launch({headless: true, args: ['--no-sandbox']});
const context = await browser.newContext({locale: 'en-US', viewport: {width: 1440, height: 1100}});
const page = await context.newPage();
const errors = [];
page.on('pageerror', error => errors.push(error.message));
await page.goto('http://localhost:5173/');
await page.locator('h1').waitFor();
assert.equal(await page.locator('h1').innerText(), 'Language & region');
await page.locator('input[value=\"ru\"]').check();
assert.equal(await page.locator('h1').innerText(), 'Язык и регион');
assert.equal(await page.locator('html').getAttribute('lang'), 'ru');
assert.equal(await page.title(), 'Язык и регион · Orbit');
assert.equal(await page.evaluate(() => localStorage.getItem('orbit.interface-language')), 'ru');
await page.reload();
await page.getByRole('heading', {name: 'Язык и регион', exact: true}).waitFor();
assert(await page.locator('input[value=\"ru\"]').isChecked());
await page.getByRole('button', {name: 'Помощь с настройкой языка'}).click();
await page.getByRole('heading', {name: 'Orbit говорит на вашем языке'}).waitFor();
await page.keyboard.press('Escape');
await page.getByRole('heading', {name: 'Orbit говорит на вашем языке'}).waitFor({state: 'hidden'});
await page.getByRole('button', {name: 'English', exact: true}).click();
assert.equal(await page.locator('h1').innerText(), 'Language & region');
await page.locator('input[value=\"en\"]').focus();
await page.keyboard.press('ArrowRight');
assert(await page.locator('input[value=\"ru\"]').isChecked());
await page.getByRole('button', {name: 'Выбрать язык браузера'}).click();
assert.equal(await page.locator('h1').innerText(), 'Language & region');
await page.screenshot({path: '/tmp/orbit-desktop.png', fullPage: true});
const secondPage = await context.newPage();
await secondPage.goto('http://localhost:5173/');
await secondPage.locator('h1').waitFor();
await page.getByRole('button', {name: 'Русский', exact: true}).click();
await secondPage.getByRole('heading', {name: 'Язык и регион', exact: true}).waitFor();
await page.setViewportSize({width: 390, height: 844});
await page.screenshot({path: '/tmp/orbit-mobile.png', fullPage: true});
assert(await page.evaluate(() => document.documentElement.scrollWidth <= window.innerWidth));
await page.setViewportSize({width: 320, height: 700});
assert(await page.evaluate(() => document.documentElement.scrollWidth <= window.innerWidth));
const ruContext = await browser.newContext({locale: 'ru-RU'});
const ruPage = await ruContext.newPage();
await ruPage.goto('http://localhost:5173/');
await ruPage.getByRole('heading', {name: 'Язык и регион', exact: true}).waitFor();
const restrictedContext = await browser.newContext({locale: 'en-US'});
await restrictedContext.addInitScript(() => { Storage.prototype.setItem = () => {throw new Error('Storage disabled');}; });
const restrictedPage = await restrictedContext.newPage();
await restrictedPage.goto('http://localhost:5173/');
await restrictedPage.getByRole('button', {name: 'Русский', exact: true}).click();
await restrictedPage.getByRole('heading', {name: 'Язык и регион', exact: true}).waitFor();
assert((await restrictedPage.getByRole('status').innerText()).includes('недоступно'));
assert.deepEqual(errors, []);
console.log('PASS: both languages, persistence, document locale/title, help dialog, keyboard control, browser default, cross-tab sync, mobile 390/320px, Russian browser default, unavailable storage, no runtime errors.');
await browser.close();
EOF"
